JavaScript — pagination over a REST endpoint:

async function fetchAll(endpoint, pageSize) {
  const out = [];
  let page = 0;
  while (true) {
    const batch = await get(`${endpoint}?offset=${page * pageSize}&limit=${pageSize}`);
    out.push(...batch);
    if (batch.length < pageSize) break;
    page++;
  }
  return out;
}

